#!/usr/bin/env python3
"""Authenticate to the NeuVector fed-master controller without printing secrets.

Tries each key in a Kubernetes secret as the admin password. Prints only which
key succeeded, the resulting role, and the token length -- never a credential.
The session token is written to a 0600 file for later probe scripts.
"""
from __future__ import annotations

import base64
import json
import os
import ssl
import subprocess
import sys
import urllib.error
import urllib.request

CTX = "rancher"
NS = "cattle-neuvector-system"
HOST = os.environ.get("NV_HOST", "192.168.7.148")
URL = f"https://{HOST}:10443"
TOKEN_PATH = os.path.join(os.path.dirname(os.path.abspath(__file__)), "nv_token")

CTXSSL = ssl.create_default_context()
CTXSSL.check_hostname = False
CTXSSL.verify_mode = ssl.CERT_NONE


def post(path: str, body: dict) -> tuple[int, dict]:
    req = urllib.request.Request(
        URL + path,
        data=json.dumps(body).encode(),
        headers={"Content-Type": "application/json"},
        method="POST",
    )
    try:
        with urllib.request.urlopen(req, context=CTXSSL, timeout=20) as r:
            return r.status, json.loads(r.read() or b"{}")
    except urllib.error.HTTPError as e:
        try:
            return e.code, json.loads(e.read() or b"{}")
        except Exception:
            return e.code, {}


def secret_values(name: str) -> dict[str, str]:
    out = subprocess.run(
        ["kubectl", f"--context={CTX}", "-n", NS, "get", "secret", name, "-o", "json"],
        capture_output=True, text=True, timeout=60,
    )
    if out.returncode != 0:
        return {}
    data = json.loads(out.stdout).get("data", {})
    vals = {}
    for k, v in data.items():
        try:
            vals[k] = base64.b64decode(v).decode("utf-8").strip()
        except Exception:
            pass
    return vals


def main() -> int:
    candidates: list[tuple[str, str]] = []
    for sec in ("neuvector-bootstrap-secret", "neuvector-manager-secret"):
        for key, val in secret_values(sec).items():
            candidates.append((f"{sec}:{key}", val))
    candidates.append(("builtin:admin", "admin"))

    print(f"trying {len(candidates)} credential candidates against {URL}")
    for label, pw in candidates:
        status, body = post("/v1/auth", {"password": {"username": "admin", "password": pw}})
        if status == 200:
            tok = body.get("token", {})
            token = tok.get("token", "")
            with open(TOKEN_PATH, "w") as fh:
                os.chmod(TOKEN_PATH, 0o600)
                fh.write(token)
            print(f"SUCCESS via {label}")
            print(f"  username={tok.get('username')} role={tok.get('role')} "
                  f"token_len={len(token)}")
            print(f"  global_permissions={tok.get('global_permissions')}")
            print(f"  token written to {TOKEN_PATH}")
            return 0
        print(f"  {label}: http={status} code={body.get('code')} {body.get('message','')}")
    print("NO CANDIDATE WORKED")
    return 1


if __name__ == "__main__":
    sys.exit(main())

